using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Sem.Authentication;
using Sem.Web.Core;
using Sem.Web.Data;
using Sem.Web.Runtime;
int checks=0;void Check(bool value,string label){if(!value)throw new Exception(label);checks++;}
var now=DateTimeOffset.Parse("2026-10-26T00:00:00Z");var file=Path.Combine(Path.GetTempPath(),"sem-profile-"+Guid.NewGuid().ToString("N")+".db");
try{
 var services=new ServiceCollection();services.AddLogging();services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlite("Data Source="+file));services.AddIdentityCore<ApplicationUser>(o=>o.Stores.SchemaVersion=IdentitySchemaVersions.Version3).AddEntityFrameworkStores<ApplicationDbContext>();await using var provider=services.BuildServiceProvider();await using var scope=provider.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();await SqliteStorageInitializer.InitializeAsync(db);
 db.Users.Add(new(){Id="synthetic-user",UserName="synthetic@example.invalid",Email="synthetic@example.invalid",DisplayName="合成管理者",Enabled=true,EmailConfirmed=true,SecurityStamp="stamp"});await db.SaveChangesAsync();await EventListFixture.Seed(db);await EventDetailFixture.Seed(db);await ProfileFixture.Seed(db);
 var identity=new IdentityOptions();ClaimsPrincipal Who(string stamp="stamp",bool duplicate=false)=>new(new ClaimsIdentity(new[]{new Claim(identity.ClaimsIdentity.UserIdClaimType,"synthetic-user"),new Claim(identity.ClaimsIdentity.SecurityStampClaimType,stamp),new Claim(AuthenticationSession.SessionClaim,"session"),new Claim(ClaimTypes.Role,"ServiceAdmin")}.Concat(duplicate?[new Claim(identity.ClaimsIdentity.UserIdClaimType,"synthetic-user")]:[]),"synthetic"));
 Task<ProfileReadResult> Read(string id="synthetic-member",bool image=false,ClaimsPrincipal? who=null)=>ProfileReader.ReadAsync(db,who??Who(),identity,id,now,image);
 var before=File.ReadAllBytes(file);var wal=File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[];
 var v=(await Read()).View!;Check(v.Id=="synthetic-member"&&!v.Own,"本人でないメンバーを最小DTOで参照");Check(v.Reading=="ごうせい"&&v.CallName=="サンプル"&&v.Icon=="🎸","保存済み読み・呼称・絵文字を保持");Check(v.Social.Length==1&&v.Social[0].Service=="合成SNS","安全なSNSだけ公開");Check(v.Answers.Length==3&&v.Answers[1].Value=="NO"&&v.Answers[2].Value is null,"有効設問の順・NO・未回答を分離");Check(v.Answers[0].Value!.StartsWith("<img"),"自己紹介は文字データのまま");Check(v.Registrations.Length==1&&v.Registrations[0].Id=="public","対象の非公開所属で閲覧者へ権限を与えない");Check(!v.Registrations[0].Spectator&&v.Registrations[0].Songs.Single().Parts.Single()=="Gt","重複観覧より現演奏を優先");Check((await Read("synthetic-watcher")).View!.Registrations.Single().Spectator,"観覧だけの現登録も表示");Check((await Read("synthetic-user")).View!.Own,"本人判定はactorと対象の一致だけ");Check((await Read("synthetic-user")).View!.Registrations.Single().Songs.Single().Parts.Single()=="Vo","本人の現割当だけを投影");
 var json=JsonSerializer.Serialize(v);foreach(var secret in new[]{"PRIVATE_DISABLED","PRIVATE_QUESTION_SENTINEL","PRIVATE_ANSWER_SENTINEL","@example.invalid","SecurityStamp","TokenHash","RegisteredBy","Email","RowVersion"})Check(!json.Contains(secret),"用途外の私的情報なし "+secret);
 Check(v.HasImage&&(await Read(image:true)).Image!.Length>24,"画像は認可後に別入口で参照");Check((await Read("synthetic-user",true)).State=="not-found","画像なしは空データや架空画像を返さない");Check(before.SequenceEqual(File.ReadAllBytes(file))&&wal.SequenceEqual(File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[]),"参照でDB／WAL不変");Check(!db.ChangeTracker.HasChanges(),"参照は既存エンティティを変更しない");
 Check((await Read(who:new ClaimsPrincipal(new ClaimsIdentity()))).State=="unauthorized","匿名は拒否");Check((await Read(who:Who("bad"))).State=="unauthorized","stamp不一致拒否");Check((await Read(who:Who(duplicate:true))).State=="unauthorized","多重本人claim拒否");Check((await Read("missing")).State=="not-found","対象欠落は非公開と同じ404契約");
 var member=await db.Users.SingleAsync(u=>u.Id=="synthetic-member");member.Enabled=false;await db.SaveChangesAsync();Check((await Read()).State=="not-found"&&(await Read(image:true)).State=="not-found","対象無効化で本文と画像を共に停止");member.Enabled=true;member.EmailConfirmed=false;await db.SaveChangesAsync();Check((await Read()).State=="not-found","対象未確認を拒否");member.EmailConfirmed=true;await db.SaveChangesAsync();
 var actor=await db.Users.SingleAsync(u=>u.Id=="synthetic-user");actor.IsAdmin=true;await db.SaveChangesAsync();Check((await Read()).View!.Registrations.Any(e=>e.Id=="hidden"),"現DB管理者だけ対象の非公開所属も参照");actor.IsAdmin=false;await db.SaveChangesAsync();Check(!(await Read()).View!.Registrations.Any(e=>e.Id=="hidden"),"古いrole claimへ権限を残さない");
 var profile=await db.UserProfiles.SingleAsync(p=>p.UserId==member.Id);profile.SocialJson="[null]";await db.SaveChangesAsync();Check((await Read()).State=="invalid","不正な保存SNSは秘密を含まない固定失敗");profile.SocialJson="[]";await db.SaveChangesAsync();var picture=await db.ProfileImages.SingleAsync();picture.Width=512;await db.SaveChangesAsync();Check((await Read(image:true)).State=="invalid","画像metadataとIHDR不一致拒否");picture.Width=1;await db.SaveChangesAsync();
 // 候補を選んでから認可。非公開100件が上位なら古い公開登録を補充しない。
 for(int n=0;n<100;n++){var id="private-"+n;db.SessionEvents.Add(new(){Id=id,Title="PRIVATE_WINDOW",ScheduledDate=$"2040-01-{n%28+1:00}T00:00:00Z",ManualPhaseOverride=true,Phases=[new(){Id=id+"-h",EventId=id,Kind="Hidden",Name="非公開",MaxPicks=0,IsActive=true},new(){Id=id+"-v",EventId=id,Kind="View",Name="閲覧",MaxPicks=0}]});db.EventSpectators.Add(new(){EventId=id,UserId=member.Id,RegisteredBy=actor.Id});}await db.SaveChangesAsync();Check((await Read()).View!.Registrations.Length==0,"最新候補100件を認可前に制限し隠れた候補を補充しない");
 actor.Enabled=false;await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","閲覧者の無効化を即反映");actor.Enabled=true;actor.EmailConfirmed=false;await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","閲覧者の未確認を拒否");actor.EmailConfirmed=true;await db.SaveChangesAsync();db.RevokedAuthSessions.Add(new(){UserId=actor.Id,TokenHash=AuthenticationSession.Hash("session"),RevokedAt=now.ToString("O")});await db.SaveChangesAsync();Check((await Read()).State=="unauthorized"&&(await Read(image:true)).State=="unauthorized","失効Cookieで本文・画像とも拒否");
 Console.WriteLine($"プロフィール参照・公開範囲・現在登録 {checks}検査: 成功（合成DBのみ）");
}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();foreach(var path in new[]{file,file+"-wal",file+"-shm"})File.Delete(path);}
